<div class="report-toolbar"><div><p class="eyebrow">RAPPORT DU JOUR</p><h2>Activité du <?= date('d/m/Y') ?></h2><p class="muted">Achats, ventes et caisse restent présentés séparément.</p></div><button class="button button-primary" onclick="window.print()">Imprimer / Enregistrer en PDF</button></div><section class="stat-grid report-stats"><article class="stat-card"><span class="stat-label">Total achats</span><strong><?= money($daily['achats'] ?? 0) ?></strong></article><article class="stat-card"><span class="stat-label">Total ventes</span><strong><?= money($daily['ventes'] ?? 0) ?></strong></article><article class="stat-card stat-card-danger"><span class="stat-label">Dépenses</span><strong><?= money($daily['depenses'] ?? 0) ?></strong></article></section><div class="report-grid"><section class="panel table-panel"><div class="panel-heading"><div><p class="eyebrow">STOCK</p><h3>Achats et ventes</h3></div></div><div class="table-wrap"><table><thead><tr><th>Heure</th><th>Type</th><th>Référence</th><th>Quantité</th><th>Total</th></tr></thead><tbody><?php foreach ($movements as $movement): ?><tr><td><?= date('H:i', strtotime($movement['date_mouvement'])) ?></td><td><?= e($movement['type_mouvement']) ?></td><td><?= e($movement['produit_nom'] ?? 'Supprimée') ?></td><td><?= e($movement['quantite']) ?></td><td><?= money($movement['montant_total']) ?></td></tr><?php endforeach; ?></tbody></table></div></section><section class="panel table-panel"><div class="panel-heading"><div><p class="eyebrow">CAISSE</p><h3>Opérations</h3></div></div><div class="table-wrap"><table><thead><tr><th>Heure</th><th>Type</th><th>Motif</th><th>Montant</th></tr></thead><tbody><?php foreach ($cash as $operation): ?><tr><td><?= date('H:i', strtotime($operation['date_operation'])) ?></td><td><?= e($operation['type_operation']) ?></td><td><?= e($operation['motif']) ?></td><td><?= money($operation['montant']) ?></td></tr><?php endforeach; ?></tbody></table></div></section></div>
